// Some portions generated by Codex

import assert from "node:assert/strict";
import test from "node:test";
import { additionsKey, takeAdditions, returnAdditions } from "../../../main/frontend/graph-explorer/graph-additions.ts";
import { queryRepository, resolveServerIdentity } from "../../../main/frontend/graph-explorer/transport.ts";
import { repositoryScope } from "../../../main/frontend/graph-explorer/repository-identity.ts";
import { saveWorkspaceText, loadWorkspaceText } from "../../../main/frontend/graph-explorer/workspace-storage.ts";
import { RdfExplorer } from "../../../main/frontend/graph-explorer/rdf-explorer.ts";

function storage() {
  const values = new Map();
  return { values, getItem: key => values.get(key) ?? null, setItem: (key,value) => values.set(key,value), removeItem: key => values.delete(key) };
}

test("same repository on two servers has separate queues and switch-back restoration", () => {
  const store = storage();
  returnAdditions("/wb", "repo", [{kind:"resource",term:"<urn:a>"}], store, "server-a");
  returnAdditions("/wb", "repo", [{kind:"resource",term:"<urn:b>"}], store, "server-b");
  assert.notEqual(additionsKey("/wb", "repo", "server-a"), additionsKey("/wb", "repo", "server-b"));
  assert.deepEqual(takeAdditions("/wb", "repo", store, "server-b"), [{kind:"resource",term:"<urn:b>"}]);
  assert.deepEqual(takeAdditions("/wb", "repo", store, "server-a"), [{kind:"resource",term:"<urn:a>"}]);
});

test("queue scopes are delimiter-safe and retain unclaimed legacy artifacts", () => {
  assert.notEqual(additionsKey("/wb|a", "repo", "server"), additionsKey("/wb", "a|repo", "server"));
  const store = storage();
  const legacy = "rdf4j-workbench-graph-additions:/wb|repo";
  store.setItem(legacy, JSON.stringify([{kind:"resource",term:"<urn:legacy>"}]));
  assert.deepEqual(takeAdditions("/wb", "repo", store, "server-a"), []);
  assert.ok(store.getItem(legacy), "unknown-server queue is retained for explicit recovery");
});

test("missing authoritative identity never consumes or creates persistent queues", () => {
  const store = storage();
  returnAdditions("/wb", "repo", [{kind:"resource",term:"<urn:a>"}], store);
  assert.equal(store.values.size, 0);
  assert.deepEqual(takeAdditions("/wb", "repo", store), []);
});


test("a cookie switch in another tab cannot merge server B results into server A", async () => {
  const original = globalThis.fetch;
  globalThis.fetch = async () => new Response(JSON.stringify({head:{vars:[]},results:{bindings:[]}}),
    {status:200,headers:{"X-Workbench-Server-Identity":"server-b"}});
  try {
    await assert.rejects(queryRepository("/wb/repositories/repo/graph", "SELECT * {}", undefined, "server-a"),
      /server connection changed/i);
    assert.deepEqual((await queryRepository("/wb/repositories/repo/graph", "SELECT * {}", undefined, "server-b")).results.bindings, []);
  } finally { globalThis.fetch = original; }
});



test("saved workspaces isolate servers and retain unknown legacy records without migration", async () => {
  const original = globalThis.localStorage;
  const store = storage();
  globalThis.localStorage = store;
  const legacy = 'graph-field-workspace-v1:/wb|repo';
  store.setItem(legacy, 'unclaimed old graph');
  try {
    const a = repositoryScope('/wb/', 'repo', 'server-a');
    const b = repositoryScope('/wb', 'repo', 'server-b');
    assert.equal(await loadWorkspaceText(a), null);
    await saveWorkspaceText('server A graph', a);
    await saveWorkspaceText('server B graph', b);
    assert.equal(await loadWorkspaceText(b), 'server B graph');
    assert.equal(await loadWorkspaceText(a), 'server A graph');
    assert.equal(store.getItem(legacy), 'unclaimed old graph');
    assert.throws(() => repositoryScope('/wb','repo',''), /identity is unavailable/);
  } finally { globalThis.localStorage = original; }
});

test("the same endpoint and RDF IDs resolve independent labels for each server", async () => {
  const endpoint='/wb/repositories/repo/graph';
  const resource={type:'uri',value:'urn:shared:server-identity-test'};
  const query=name=>async()=>({results:{bindings:[{resource,label:{type:'literal',value:name,'xml:lang':'en'},
    labelProperty:{type:'uri',value:'http://www.w3.org/2000/01/rdf-schema#label'}}]}});
  const a=new RdfExplorer(endpoint,['en'],query('Server A label'),'default',false,false,repositoryScope('/wb','repo','server-a'));
  const b=new RdfExplorer(endpoint,['en'],query('Server B label'),'default',false,false,repositoryScope('/wb','repo','server-b'));
  try {
    await a.resolve([resource.value]);
    assert.equal(a.label(resource.value),'Server A label');
    assert.notEqual(b.label(resource.value),'Server A label');
    await b.resolve([resource.value]);
    assert.equal(b.label(resource.value),'Server B label');
    assert.equal(a.label(resource.value),'Server A label');
  } finally { a.dispose();b.dispose(); }
});

test("standalone entry resolves the authoritative identity with a no-store page request", async () => {
  const original=globalThis.fetch;
  const requests=[];
  globalThis.fetch=async(url,options)=>{requests.push([url,options]);return new Response('',{headers:{'X-Workbench-Server-Identity':'server-a'}});};
  try {
    assert.equal(await resolveServerIdentity('/wb/repositories/repo/graph'),'server-a');
    assert.equal(requests[0][1].cache,'no-store');
    assert.equal(requests[0][1].credentials,'same-origin');
    globalThis.fetch=async()=>new Response('');
    await assert.rejects(resolveServerIdentity('/wb/repositories/repo/graph'),/could not be identified/);
  } finally {globalThis.fetch=original;}
});
